<template><div class="page"><h2>数据管理</h2><el-form v-if="isAdmin" :model="form" inline><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="故障类型"><el-input v-model="form.fault_type"/></el-form-item><el-form-item label="注入时间"><el-input-number v-model="form.injection_time"/></el-form-item><el-form-item label="发射次数"><el-input-number v-model="form.launch_number"/></el-form-item><el-form-item label="退化程度"><el-input-number v-model="form.degradation" :min="0" :max="1" :step=".1"/></el-form-item><el-form-item label="系统"><el-input v-model="form.system"/></el-form-item><el-form-item label="部件"><el-input v-model="form.component"/></el-form-item><el-form-item><input type="file" accept=".csv" @change="form.file=$event.target.files[0]"/><el-button type="primary" @click="upload">上传</el-button></el-form-item></el-form><el-table :data="rows"><el-table-column prop="name" label="文件"/><el-table-column prop="source" label="来源"/><el-table-column prop="fault_type" label="故障类型"/><el-table-column prop="injection_time" label="注入时间"/><el-table-column prop="launch_number" label="发射次数"/><el-table-column prop="degradation" label="退化程度"/><el-table-column prop="system" label="系统"/><el-table-column prop="component" label="部件"/><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="download(s.row)">下载 CSV</el-button><el-button v-if="isAdmin" link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></div></template>
<script setup>import{ref,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';const rows=ref([]),form=ref({source:'offline'});async function load(){const r=await fetch('/api/v1/datasets/',{credentials:'include'});if(!r.ok)throw Error('数据集加载失败');rows.value=await r.json()}async function upload(){const f=new FormData();Object.entries(form.value).forEach(([k,v])=>v!==undefined&&v!==null&&f.append(k,v));const r=await fetch('/api/v1/datasets/',{method:'POST',credentials:'include',headers:csrfHeaders(),body:f});if(!r.ok)return ElMessage.error('上传失败：权限不足或文件无效');form.value={source:'offline'};await load();ElMessage.success('数据集已上传')}const isAdmin=ref(false);function csrfHeaders(){const token=document.cookie.split('; ').find(x=>x.startsWith('csrftoken='))?.slice(10);return token?{'X-CSRFToken':decodeURIComponent(token)}:{}}function download(row){window.open(`/api/v1/datasets/${row.id}/download/`,'_blank')}async function remove(row){try{await ElMessageBox.confirm(`将永久删除“${row.name}”及其 CSV 文件。`,'删除数据集',{type:'warning'});const r=await fetch(`/api/v1/datasets/${row.id}/`,{method:'DELETE',credentials:'include',headers:csrfHeaders()});if(!r.ok)throw Error();await load();ElMessage.success('数据集已删除')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error('删除失败：权限不足或数据集不存在')}}onMounted(async()=>{try{const r=await fetch('/api/v1/permissions/profile/',{credentials:'include'});if(r.ok)isAdmin.value=(await r.json()).role==='admin';await load()}catch(e){ElMessage.error(e.message)}})</script><style scoped>.page{max-width:1400px}.el-form{padding:14px;background:#f7f9fc;margin-bottom:18px}.el-form-item{margin-bottom:12px}</style>
